// Liest die Rechnungsanschrift von zwoelf Buchungen und meldet nur
// die Feldnamen und Werttypen. Keine Klardaten, keine Namen, keine Anschriften.

const auth = $('S21 Token holen').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const kennungen = $input.all().map((z) => z.json.booking_id).filter(Boolean);

async function einzeln(kennung) {
  const antwort = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://app1.edoobox.com/v2/booking/${encodeURIComponent(kennung)}/data`,
    headers,
    json: true,
    returnFullResponse: true,
    timeout: 60000,
    ignoreHttpStatusErrors: true,
  });
  if (antwort.statusCode !== 200) return null;
  const roh = antwort.body?.data;
  return Array.isArray(roh) ? roh[0] : roh;
}

const holen = einzeln.bind(this);
const saetze = (await Promise.all(kennungen.map((k) => holen(k)))).filter(Boolean);

function art(wert) {
  if (wert === null) return 'null';
  if (Array.isArray(wert)) return `liste[${wert.length}]`;
  if (typeof wert === 'object') return `objekt{${Object.keys(wert).join(',')}}`;
  if (typeof wert === 'boolean') return `wahrheitswert:${wert}`;
  if (typeof wert === 'string') return wert === '' ? 'text:leer' : `text:gefuellt(${wert.length})`;
  return typeof wert;
}

// Nur bei Feldern, die erkennbar Land oder Steuerkennung betreffen,
// werden die tatsaechlichen Werte gezeigt. Alles andere bleibt verdeckt.
const offen = /land|country|vat|ust|tax|steuer|b2b|company|firma|zip|plz/i;

const uebersicht = new Map();

for (const b of saetze) {
  const a = b?.invoice_address;
  if (!a || typeof a !== 'object') continue;
  for (const [feld, wert] of Object.entries(a)) {
    if (!uebersicht.has(feld)) uebersicht.set(feld, { feld, arten: new Set(), werte: new Set() });
    const e = uebersicht.get(feld);
    e.arten.add(art(wert));
    if (offen.test(feld) && (typeof wert === 'string' || typeof wert === 'boolean' || typeof wert === 'number')) {
      const t = String(wert);
      e.werte.add(t.length > 24 ? t.slice(0, 24) + '…' : t);
    }
  }
}

const zeilen = [...uebersicht.values()]
  .sort((a, b) => a.feld.localeCompare(b.feld))
  .map((e) => ({
    json: {
      schritt: 'S21',
      feld: e.feld,
      arten: [...e.arten].slice(0, 4).join(' | '),
      beispielwerte: [...e.werte].slice(0, 6).join(' | '),
    },
  }));

zeilen.unshift({
  json: {
    schritt: 'S21',
    feld: '(Probe)',
    arten: `${saetze.length} von ${kennungen.length} Buchungen gelesen`,
    beispielwerte: '',
  },
});

return zeilen;
